    [5341] = {"Barov Family Fortune",60,52,"H","Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",{11022},{},{},{11022},{},{},{},{13471,13448,13450,13451},{},nil,nil,nil,{}},
    [5342] = {"The Last Barov",60,52,"H","Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.  Be warned, Weldon will probably be well protected by Alliance scum.",{11022},{},{},{11022},{},{5341},{},{13469},{14022},nil,nil,{5341},{}},
    [5343] = {"Barov Family Fortune",60,52,"A","Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.",{11023},{},{},{11023},{},{},{},{13471,13448,13450,13451},{},nil,nil,nil,{}},
