    [5382] = {"Doctor Theolen Krastinov, the Butcher",60,55,nil,"Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete. ",{11216},{},{},{11216},{},{},{},{},{},nil,nil,nil,{11261}},
